// London sky uses solar elevation; traffic is a time-of-day simulation, not live road data.
function streetConditions(date=new Date()){
 const day=(date-Date.UTC(date.getUTCFullYear(),0,0))/86400000,utc=date.getUTCHours()*60+date.getUTCMinutes()+date.getUTCSeconds()/60,gamma=2*Math.PI/365*(day-1);
 const eq=229.18*(.000075+.001868*Math.cos(gamma)-.032077*Math.sin(gamma)-.014615*Math.cos(2*gamma)-.040849*Math.sin(2*gamma));
 const dec=.006918-.399912*Math.cos(gamma)+.070257*Math.sin(gamma)-.006758*Math.cos(2*gamma)+.000907*Math.sin(2*gamma)-.002697*Math.cos(3*gamma)+.00148*Math.sin(3*gamma);
 const hourAngle=((utc+4*(-.089)+eq)/4-180)*Math.PI/180,lat=51.5256*Math.PI/180,alt=Math.asin(Math.sin(lat)*Math.sin(dec)+Math.cos(lat)*Math.cos(dec)*Math.cos(hourAngle))*180/Math.PI;
 const light=Math.max(0,Math.min(1,(alt+6)/18)),parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'numeric',minute:'numeric',hourCycle:'h23',weekday:'short'}).formatToParts(date),values=Object.fromEntries(parts.map(p=>[p.type,p.value])),h=+values.hour+(+values.minute)/60,weekday=!['Sat','Sun'].includes(values.weekday),rush=weekday&&(h>=7&&h<10||h>=16&&h<19),night=h<6||h>=23;
 return {light,twilight:Math.max(0,1-Math.abs(alt)/7),count:rush?3:night?1:2,lap:night?1900:rush?900:1200,speed:rush?22:night?35:30,traffic:rush?'RUSH HOUR':night?'QUIET STREET':'CITY FLOW'};
}


