function walkPath(room,start,target,ignore){const step=8,cols=80,rows=40;const key=(x,y)=>y*cols+x;const startX=Math.max(1,Math.min(78,Math.round(start.x/step))),startY=Math.max(1,Math.min(38,Math.round(start.y/step))),endX=Math.round(target.x/step),endY=Math.round(target.y/step),goal=key(endX,endY);const people=state.guests.filter(p=>p!==ignore&&p.r===room).map(p=>({x:p.x-origin[room].x,y:p.y-origin[room].y,r:26}));for(const [n,a] of Object.entries(actors))if(a.room===room&&ignore?.name!==n)people.push({x:a.x,y:a.y,r:32});if(ignore!==scene.player&&state.seatRoom===room)people.push({x:room==='front'?312:400,y:270,r:18});const blocked=(x,y)=>{if(x<1||x>=cols-1||y<1||y>=rows-1)return true;if(key(x,y)===goal)return false;const px=x*step,py=y*step;if((WALK_BLOCKS[room]||[]).some(([bx,by,bw,bh])=>px>bx-4&&px<bx+bw+4&&py>by-4&&py<by+bh+4))return true;return people.some(p=>Math.hypot(px-p.x,py-p.y)<p.r);};const queue=[[startX,startY]],prev=new Map([[key(startX,startY),null]]);let head=0;while(head<queue.length){const [x,y]=queue[head++],k=key(x,y);if(k===goal){const path=[];let at=k;while(at!==null){path.push({x:(at%cols)*step,y:Math.floor(at/cols)*step});at=prev.get(at);}path.reverse();path.push(target);return path;}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,nk=key(nx,ny);if(!prev.has(nk)&&!blocked(nx,ny)){prev.set(nk,k);queue.push([nx,ny]);}}}return null;}
